  // set; otherwise it is uninitialised parser-stack garbage, not NULL.
  struct RSQueryNode *tag = NewTagNode(ctx->sctx->spec ? field->fs : NULL);
  QueryNode_AddChild(tag, NewLexRangeNode_WithParams(ctx, bound, lower, inclusive));
  return tag;
